def transform(wb):
    ws = wb['Sheet1']
    cv = cached_values.get('Sheet1', {})
    first_row = 5
    last_row = 43
    for r in range(first_row, last_row + 1):
        ws.cell(row=r, column=26).value = None
    blocks = []
    current = []
    for r in range(first_row, last_row + 1):
        row_has_data = False
        for c in range(1, 25):
            v = ws.cell(row=r, column=c).value
            if v is not None and v != '':
                row_has_data = True
                break
        if row_has_data:
            current.append(r)
        else:
            if current:
                blocks.append(current)
                current = []
    if current:
        blocks.append(current)
    for block in blocks:
        scores = []
        for r in block:
            v = cv.get(f'K{r}')
            if v is None:
                v = ws.cell(row=r, column=11).value
            if v is None or v == '':
                score = 0.0
            else:
                score = float(v)
            scores.append(score)
        max_score = None
        for score in scores:
            if max_score is None or score > max_score:
                max_score = score
        for i in range(len(block)):
            r = block[i]
            if scores[i] == max_score:
                ws.cell(row=r, column=26).value = 'Y'
            else:
                ws.cell(row=r, column=26).value = 'N'
